// Parse user-uploaded context documents
const inputData = $('Extract Input Data').first().json;
const contextFiles = inputData.context_files || [];
const parsedDocs = [];

for (const file of contextFiles) {
  try {
    if (file.data) {
      const fileData = Buffer.from(file.data, 'base64').toString('utf-8');
      parsedDocs.push({
        filename: file.name || 'unknown',
        content: fileData,
        type: file.type || 'unknown'
      });
    }
  } catch (error) {
    console.error(`Failed to parse ${file.name}:`, error.message);
  }
}

return {
  context_documents: parsedDocs,
  context_text: parsedDocs.map(d => `--- ${d.filename} ---\n${d.content}`).join('\n\n'),
  context_count: parsedDocs.length
};

