// Prepare all inputs for Gemini - properly extract binary data from Google Drive

// Helper function to extract text from Google Drive binary data
function extractTextFromBinary(nodeData) {
  try {
    // Try to get binary data
    const binaryData = nodeData.binary;
    if (binaryData) {
      // Get the first binary key (usually 'data' or filename)
      const binaryKey = Object.keys(binaryData)[0];
      if (binaryKey && binaryData[binaryKey]) {
        // The data is base64 encoded
        const base64Data = binaryData[binaryKey].data;
        if (base64Data) {
          return Buffer.from(base64Data, 'base64').toString('utf-8');
        }
      }
    }
    // Fallback to json.data if exists
    if (nodeData.json && nodeData.json.data) {
      return String(nodeData.json.data);
    }
    return null;
  } catch (e) {
    console.error('Error extracting binary:', e.message);
    return null;
  }
}

// Extract MSA criteria
const msaNode = $('Load MSA Criteria').first();
let msaCriteria = extractTextFromBinary(msaNode);
if (!msaCriteria) {
  msaCriteria = 'MSA Criteria: Evaluate population >400k, growth >1%, employment growth >1.5%, income growth >2%, job diversity, unemployment <5%, vacancy 4-6%, permits trending, absorption positive, low environmental risk, cap rate spread >150bps, landlord-friendly laws, affordability index, proximity to tier 1 MSA.';
}

// Extract SubMarket criteria
const subNode = $('Load SubMarket Criteria').first();
let subCriteria = extractTextFromBinary(subNode);
if (!subCriteria) {
  subCriteria = 'SubMarket Criteria: Crime below MSA average, schools rated 6+, transport avoidance >0.5mi, amenities 1-2mi (goldilocks), school proximity, transit access, path of growth, zoning protections, renter density appropriate, government stability, cluster growth, proximity to MF assets, reasonable taxes, historical appreciation >3%.';
}

// Extract research data
const researchNode = $('Perplexity Research').first();
let researchData = researchNode.json?.choices?.[0]?.message?.content || 'Research data not available';

// Extract context docs
const contextNode = $('Parse Context Docs').first();
let contextDocs = contextNode.json?.context_text || 'No context documents uploaded';

// Extract address and deal name
const inputNode = $('Extract Input Data').first();
const address = inputNode.json?.address || 'Address not provided';
const dealName = inputNode.json?.deal_name || 'Unnamed Deal';

return {
  msa_criteria: msaCriteria,
  submarket_criteria: subCriteria,
  research_data: researchData,
  context_docs: contextDocs,
  address: address,
  deal_name: dealName
};

